// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    // fuzzed params: actor is the caller who will attempt to call owned() then transferOwnership;
    // newOwner is the address they attempt to set as owner.
    function testFuzz_property(address actor, address newOwner) public {
        // keep addresses non-zero to be meaningful
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));

        // Ensure actor has ETH so calls (if payable) won't fail; not strictly necessary but harmless
        vm.deal(actor, 1 ether);

        // Record the original owner as reported by the contract
        address origOwner = c.owner();

        // Actor calls owned() (an owner-only entrypoint). In the correct contract this will only succeed
        // (enter owner's body) when actor == origOwner; in the mutant it will always succeed.
        bool okCall;
        vm.prank(actor);
        try c.owned() {
            okCall = true;
        } catch {
            okCall = false;
        }

        // After attempting owned(), actor attempts to call transferOwnership to set newOwner.
        // In the correct contract this will only succeed if actor == origOwner. We capture whether it succeeds.
        bool okTransfer;
        vm.prank(actor);
        try c.transferOwnership(newOwner) {
            okTransfer = true;
        } catch {
            okTransfer = false;
        }

        // FINAL OBSERVATION: the contract's owner must equal origOwner unless the caller was the original owner
        // (i.e., only the original owner may change ownership). This is the universal property the reference satisfies.
        // We assert that: if actor != origOwner then owner() remains origOwner.
        if (actor != origOwner) {
            assertTrue(c.owner() == origOwner);
        } else {
            // if actor == origOwner, transferOwnership may have succeeded setting newOwner (or left unchanged)
            // no further assertion needed other than a tautology check reading c
            assertTrue(c.owner() == origOwner || c.owner() == newOwner);
        }
    }
}
